import json, subprocess
branches = ['17-fix-closed-issue', '18-fix-deleted-issue', 'feat/linked', 'feat/merged', 'feat/squashed', 'feat/unpublished', 'fix/closed']
checks = {}
for branch in branches:
    local = 'refs/heads/' + branch
    refs = ['refs/remotes/origin/' + branch, 'refs/remotes/origin/main']
    checks[branch] = {}
    for ref in refs:
        result = subprocess.run(['git', 'merge-base', '--is-ancestor', local, ref], capture_output=True, text=True)
        if result.returncode not in (0, 1):
            raise RuntimeError(result.stderr)
        checks[branch][ref] = result.returncode == 0
print(json.dumps(checks, sort_keys=True))
